class OnlineStatus : public QObject {
    Q_OBJECT
public:
    bool isOnline() const { return online_; }
public slots:
    void setOnline(bool online) {
        if (online == online_) return;
        online_ = online;
        emit onlineChanged(online);
    }
signals:
    void onlineChanged(bool online);
private:
    bool online_ = true;
};

QObject::connect(status, &OnlineStatus::onlineChanged, badge, &Badge::setOnline);
